  const VERB_STARTS = new Set([
    "accept", "acquire", "address", "adopt", "analyze", "apply", "assess", "attend", "balance", "begin", "build", "calculate", "capture", "carry", "challenge", "change", "compare", "complete", "conduct", "confirm", "consult", "contact", "control", "create", "cross", "decrease", "define", "describe", "design", "detect", "develop", "distinguish", "earn", "enter", "establish", "estimate", "examine", "expand", "express", "find", "form", "give", "grow", "hold", "identify", "improve", "include", "increase", "invest", "launch", "limit", "maintain", "make", "manage", "measure", "obtain", "observe", "paint", "pass", "pay", "perform", "plant", "prevent", "promote", "protect", "provide", "question", "raise", "reach", "read", "receive", "record", "reduce", "remove", "request", "restore", "seek", "shape", "sign", "speak", "store", "study", "support", "suppress", "take", "test", "treat", "use", "write"
  ]);

  const POS_TR = { n: "isim", v: "fiil", adj: "sıfat", adv: "zarf", chunk: "kalıp" };

  // A compact set of hand-written examples covers collocations whose surface
  // form cannot be inserted safely into the generic sentence templates.  This
  // keeps every cloze grammatical while preserving the exact target lemma.
  const MANUAL_EXAMPLES = {
    distinguish: "Researchers must distinguish between correlation and causation before drawing a conclusion.",
    evolve: "A scientific explanation may evolve over time as new evidence becomes available.",
    persist: "Small measurement errors may persist over time if the instrument is not recalibrated.",
    deteriorate: "Environmental conditions may deteriorate when a system loses its resilience.",
    recover: "A damaged ecosystem may recover from disturbance when the original stressor is removed.",
    contend: "Some speakers contend that the available evidence supports a different conclusion.",
    maintain: "Several scholars maintain that social context shapes individual behavior.",
    disagree: "Researchers may disagree with one another while interpreting the same evidence.",
    elaborate: "A speaker should elaborate on the main point with a relevant example.",
    correlate: "Analysts may correlate strongly related variables before testing a broader model.",
    comply: "Public institutions must comply with the law when enforcing a regulation.",
    plagiarism: "A clear citation policy helps students avoid plagiarism in academic assignments.",
    controversy: "A poorly supported claim may cause controversy during an academic discussion.",
    participant: "Each study participant received the same instructions before the experiment.",
    control: "The control group did not receive the experimental intervention.",
    penalty: "A court may impose a penalty when an organization violates the law.",
    medication: "Patients should take medication exactly as directed by a clinician.",
    immunity: "A population may acquire immunity through vaccination or previous exposure."
  };

  function upperFirst(text) {
    return text.charAt(0).toUpperCase() + text.slice(1);
  }

  function generatedExample(row, topic) {
    const lemma = row[0];
    const pos = row[3];
    const collocation = row[5].split(";")[0];
    if (row[6]) return row[6];
    if (MANUAL_EXAMPLES[lemma]) return MANUAL_EXAMPLES[lemma];
    if (pos === "adj") {
      return `${upperFirst(collocation)} is central to the lecture's explanation of ${topic.domain}.`;
    }
    if (pos === "adv") {
      return `The researchers proceeded ${collocation} while documenting each stage.`;
    }
    const first = collocation.toLowerCase().split(/\s+/)[0];
    if (pos === "v" || VERB_STARTS.has(first)) {
      return `${topic.subject} may ${collocation} when examining ${topic.domain}.`;
    }
    const article = /^[A-Z]/.test(collocation) ? "" : "the ";
    return `${upperFirst(article + collocation)} can influence how scholars understand ${topic.domain}.`;
  }

  function makeFamily(encoded, lemma, pos) {
    const parts = encoded.split("|");
    const family = {
      noun: parts[0] || null,
      verb: parts[1] || null,
      adjective: parts[2] || null,
      adverb: parts[3] || null
    };
    const key = { n: "noun", v: "verb", adj: "adjective", adv: "adverb" }[pos];
    if (key && !family[key]) family[key] = lemma;
    return family;
  }

  function replaceFirstInsensitive(text, search, replacement) {
    const escaped = search.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return text.replace(new RegExp(escaped, "i"), replacement);
  }

  const expanded = [];
  TOPICS.forEach((topic) => {
    const rows = RAW[topic.id] || [];
    rows.forEach((row, index) => {
      const collocations = row[5].split(";").map((value) => value.trim()).filter(Boolean);
      const example = generatedExample(row, topic);
      const peers = rows.filter((candidate) => candidate !== row && candidate[3] === row[3]);
      const fallbackPeers = peers.length >= 3 ? peers : rows.filter((candidate) => candidate !== row);
      const offset = fallbackPeers.indexOf(row);
      const distractors = [0, 1, 2].map((step) => fallbackPeers[(index + step + 1 + Math.max(0, offset)) % fallbackPeers.length][0]);
      const recognitionChoices = [row[1], ...[0, 1, 2].map((step) => rows[(index + step + 7) % rows.length][1])];
      expanded.push({
        id: `x-${topic.id}-${String(index + 1).padStart(2, "0")}`,
        lemma: row[0],
        type: row[3] === "chunk" ? "chunk" : "word",
        pos: row[3],
        tr: row[1],
        level: row[2],
        topic: topic.id,
        topicId: topic.id,
        family: makeFamily(row[4], row[0], row[3]),
        collocations,
        example,
        cloze: replaceFirstInsensitive(example, row[0], "___"),
        distractors,
        recognitionChoices,
        note: `“${row[0]}” ${POS_TR[row[3]]} olarak özellikle “${collocations[0]}” kullanımında görülür.`,
        sourceTag: "OPAL-informed curriculum",
        active: true
      });
    });
  });

  const existingMeta = window.TOPIC_META && !Array.isArray(window.TOPIC_META) ? window.TOPIC_META : {};
  window.TOPIC_META = { ...existingMeta };
  TOPICS.forEach((topic) => {
    window.TOPIC_META[topic.id] = {
      id: topic.id,
      label: topic.titleTr,
      title: topic.title,
      subject: topic.subject,
      domain: topic.domain
    };
  });
  window.EXPANDED_VOCAB_DATA = expanded;
  window.VOCAB_DATA = [...(window.VOCAB_DATA || []), ...expanded];
  window.VOCAB_SOURCE_INFO = {
    selection: "OPAL-informed; supplemented with TOEFL-relevant academic subject vocabulary",
    authorship: "All Turkish glosses, collocations, examples, cloze sentences and notes are original.",
    levelNote: "B2, C1 and C2 labels are pedagogical guidance for this curriculum, not official Oxford CEFR labels.",
    offline: true
  };
